#include "Studio.h"
#include <cstdlib>
namespace pulse {
using namespace juce;
namespace {
bool tuningNumber(String text,double low,double high,double& value){text=text.trim();auto bytes=text.toRawUTF8();char* end=nullptr;value=std::strtod(bytes,&end);return text.isNotEmpty()&&end!=bytes&&*end==0&&std::isfinite(value)&&value>=low&&value<=high;}
}
bool Studio::microTuningContext(uint64_t expected,int track)const{
    return expected==revision&&selectedTrack==track&&track>=0&&track<(int)project.tracks.size()&&!project.tracks[(size_t)track].isBus&&!isDrum(project.tracks[(size_t)track].instrument)&&!recording&&!recorder.isActive()&&!pendingNoteTool();
}
bool Studio::applyMicroTuning(const MicroTuning& tuning,uint64_t expected,int track){
    if(!microTuningContext(expected,track)){status="Channel or project changed, or a take/preview is active. Reopen microtonal tuning.";return false;}
    auto valid=validateMicroTuning(tuning);if(valid.failed()){status=valid.getErrorMessage();return false;}
    auto& target=project.tracks[(size_t)track];if(target.tuning==tuning){status="Channel tuning is already set.";return true;}
    releaseKeys();checkpoint();target.tuning=tuning;changed();status=tuning.enabled?"Tuning: "+tuning.name+". New notes use the table; piano keys show actual Hz. MIDI export keeps ordinary note numbers.":"Channel tuning bypassed; saved table retained. One Undo restores the change.";return true;
}
void Studio::editMicroTuning(MicroTuning tuning,uint64_t expected,int track,int pitch){
    if(!microTuningContext(expected,track)){status="Select a pitched channel and finish any take or preview first.";return;}releaseKeys();
    auto draft=std::make_shared<MicroTuning>(std::move(tuning));auto selected=std::make_shared<int>(jlimit(0,127,pitch));
    auto* dialog=new AlertWindow("Channel microtonal tuning","Offsets are cents relative to 12-tone equal temperament at the reference A4. Edit any of the 128 keys; changes stay in this draft until Apply. Bypass retains the table. Sample root/fine calibration is separate. Drums, Playlist audio and raw sample preview keep their original pitch. Existing held synth notes retain their onset tuning.",MessageBoxIconType::NoIcon,this);
    dialog->addTextEditor("name",draft->name,"Table name");dialog->addComboBox("enabled",{"Bypassed","Enabled"},"Channel tuning");dialog->getComboBoxComponent("enabled")->setSelectedItemIndex(draft->enabled?1:0,dontSendNotification);
    dialog->addTextEditor("reference",String(draft->referenceHz,8),"Reference A4 (220-880 Hz)");
    StringArray keys;for(int n=0;n<128;++n)keys.add(samplerNoteName(n)+" / MIDI "+String(n)+" / "+microTuningLabel(*draft,n));dialog->addComboBox("key",keys,"Key (labels are MIDI positions; sounding pitch follows the table)");auto* combo=dialog->getComboBoxComponent("key");combo->setSelectedItemIndex(*selected,dontSendNotification);
    dialog->addTextEditor("cents",String(draft->cents[(size_t)*selected],10),"This key offset (-24000 to +24000 cents)");
    auto safeDialog=Component::SafePointer<AlertWindow>(dialog);combo->onChange=[safeDialog,draft,selected]{if(!safeDialog)return;auto* key=safeDialog->getComboBoxComponent("key");double value;if(!tuningNumber(safeDialog->getTextEditorContents("cents"),-24000,24000,value)){key->setSelectedItemIndex(*selected,dontSendNotification);safeDialog->getTextEditor("cents")->grabKeyboardFocus();return;}if(safeDialog->getTextEditorContents("cents")!=String(draft->cents[(size_t)*selected],10))draft->cents[(size_t)*selected]=value;*selected=key->getSelectedItemIndex();safeDialog->getTextEditor("cents")->setText(String(draft->cents[(size_t)*selected],10));};
    dialog->addButton("Apply",1,KeyPress(KeyPress::returnKey));dialog->addButton("Cancel",0,KeyPress(KeyPress::escapeKey));auto safe=Component::SafePointer<Studio>(this);
    dialog->enterModalState(true,ModalCallbackFunction::create([safe,dialog,draft,selected,expected,track](int result){if(!safe||result!=1)return;double cents,reference;if(!tuningNumber(dialog->getTextEditorContents("cents"),-24000,24000,cents)||!tuningNumber(dialog->getTextEditorContents("reference"),220,880,reference)){safe->status="Enter finite numeric cents and reference frequency within the displayed ranges. Nothing changed.";return;}
        if(dialog->getTextEditorContents("cents")!=String(draft->cents[(size_t)*selected],10))draft->cents[(size_t)*selected]=cents;draft->name=dialog->getTextEditorContents("name").trim();if(dialog->getTextEditorContents("reference")!=String(draft->referenceHz,8))draft->referenceHz=reference;draft->enabled=dialog->getComboBoxComponent("enabled")->getSelectedItemIndex()==1;safe->applyMicroTuning(*draft,expected,track);
    }),true);
}
void Studio::editEqualTuning(uint64_t expected,int track){
    if(!microTuningContext(expected,track))return;auto* dialog=new AlertWindow("Equal divisions of the octave","Each next MIDI key advances one scale degree. The root retains its ordinary 12-TET frequency at the chosen reference A4. For example, 24 divisions use 24 adjacent keys per octave. Review and edit the resulting table before Apply.",MessageBoxIconType::NoIcon,this);
    dialog->addTextEditor("divisions","24","Divisions (whole number, 5-72)");dialog->addTextEditor("root","60","Root MIDI key (0-127; 60 = C4)");dialog->addTextEditor("reference",String(project.tracks[(size_t)track].tuning.referenceHz,8),"Reference A4 (220-880 Hz)");dialog->addButton("Create draft",1,KeyPress(KeyPress::returnKey));dialog->addButton("Cancel",0,KeyPress(KeyPress::escapeKey));auto safe=Component::SafePointer<Studio>(this);
    dialog->enterModalState(true,ModalCallbackFunction::create([safe,dialog,expected,track](int result){if(!safe||result!=1||!safe->microTuningContext(expected,track))return;double divisions,root,reference;if(!tuningNumber(dialog->getTextEditorContents("divisions"),5,72,divisions)||divisions!=std::floor(divisions)||!tuningNumber(dialog->getTextEditorContents("root"),0,127,root)||root!=std::floor(root)||!tuningNumber(dialog->getTextEditorContents("reference"),220,880,reference)){safe->status="Enter whole-number divisions/root and a valid reference frequency.";return;}MicroTuning draft;auto valid=equalDivisionTuning((int)divisions,(int)root,reference,draft);if(valid.failed())safe->status=valid.getErrorMessage();else safe->editMicroTuning(draft,expected,track,(int)root);
    }),true);
}
void Studio::importMicroTuning(uint64_t expected,int track){
    if(!microTuningContext(expected,track))return;auto* dialog=new AlertWindow("Import tuning","Choose a local Scala .scl or Pulse .pulsetuning file, up to 64 KiB. Scala advances one scale degree per MIDI key and anchors the root at its 12-TET frequency. Non-octave periods work. Pulse presets already contain the complete mapping. Scala .kbm mappings are not supported.",MessageBoxIconType::NoIcon,this);
    dialog->addTextEditor("root","60","Scala root MIDI key (0-127)");dialog->addTextEditor("reference",String(project.tracks[(size_t)track].tuning.referenceHz,8),"Scala reference A4 (220-880 Hz)");dialog->addButton("Choose file",1,KeyPress(KeyPress::returnKey));dialog->addButton("Cancel",0,KeyPress(KeyPress::escapeKey));auto safe=Component::SafePointer<Studio>(this);
    dialog->enterModalState(true,ModalCallbackFunction::create([safe,dialog,expected,track](int result){if(!safe||result!=1||!safe->microTuningContext(expected,track))return;double root,reference;if(!tuningNumber(dialog->getTextEditorContents("root"),0,127,root)||root!=std::floor(root)||!tuningNumber(dialog->getTextEditorContents("reference"),220,880,reference)){safe->status="Choose a whole-number Scala root and valid reference frequency.";return;}
        safe->chooser=std::make_unique<FileChooser>("Import channel tuning",safe->root,"*.scl;*.pulsetuning");safe->chooser->launchAsync(FileBrowserComponent::openMode|FileBrowserComponent::canSelectFiles,[safe,expected,track,root,reference](const FileChooser& fc){if(!safe||!safe->microTuningContext(expected,track))return;auto file=fc.getResult();if(file==File())return;MicroTuning draft;auto valid=loadMicroTuning(file,(int)root,reference,draft);if(valid.failed())safe->status=valid.getErrorMessage();else safe->editMicroTuning(draft,expected,track,(int)root);});
    }),true);
}
void Studio::showMicroTuning(){
    auto expected=revision;int track=selectedTrack;if(!microTuningContext(expected,track)){status="Select a pitched instrument channel and finish any take or preview first.";return;}
    const auto tuning=project.tracks[(size_t)track].tuning;PopupMenu menu;menu.addSectionHeader("Channel tuning: "+tuning.name);menu.addItem(1,"Edit all keys / reference A4...");menu.addItem(2,"Enable table",true,tuning.enabled);menu.addItem(3,"Equal divisions of octave...");menu.addItem(4,"Import Scala / tuning preset...");menu.addItem(5,"Save tuning preset...");menu.addSeparator();menu.addItem(6,"Reset to standard 12-TET / A4 440 Hz");auto safe=Component::SafePointer<Studio>(this);
    menu.showMenuAsync(menuOptions(microTuningOpen),[safe,expected,track,tuning](int result){if(!safe||result==0)return;if(!safe->microTuningContext(expected,track)){safe->status="Channel or project changed. Reopen channel tuning.";return;}if(result==1)safe->editMicroTuning(tuning,expected,track);else if(result==2){auto next=tuning;next.enabled=!next.enabled;safe->applyMicroTuning(next,expected,track);}else if(result==3)safe->editEqualTuning(expected,track);else if(result==4)safe->importMicroTuning(expected,track);else if(result==6)safe->applyMicroTuning(MicroTuning{},expected,track);else if(result==5){safe->chooser=std::make_unique<FileChooser>("Save channel tuning",safe->root.getChildFile("Channel tuning.pulsetuning"),"*.pulsetuning");safe->chooser->launchAsync(FileBrowserComponent::saveMode|FileBrowserComponent::canSelectFiles|FileBrowserComponent::warnAboutOverwriting,[safe,expected,track,tuning](const FileChooser& fc){if(!safe||!safe->microTuningContext(expected,track)||fc.getResult()==File())return;auto valid=saveMicroTuning(tuning,fc.getResult().withFileExtension("pulsetuning"));safe->status=valid.wasOk()?"Tuning preset saved locally, including every key and bypass state.":valid.getErrorMessage();});}});
}
}
